import math

def integrand(x, n):
    sin_x = math.sin(x)
    return (sin_x ** n) / (1.0 - sin_x)

def trapz(f, a, b, n_steps, n_power):
    h = (b - a) / n_steps
    total = 0.5 * (f(a, n_power) + f(b, n_power))
    for i in range(1, n_steps):
        total += f(a + i * h, n_power)
    return total * h

def main():
    epsilon = 0.1
    b = math.pi / 2 - epsilon
    a = 0.0

    n_values = [10, 50, 100, 500, 1000]
