import itertools
import json

def solve():
    movies = ['H', 'M', 'R', 'S', 'W']
    # Screens: 
    # S1_7, S1_9
    # S2_7, S2_9
    # S3_8

    slots = [
        ('1', 7), ('1', 9),
        ('2', 7), ('2', 9),
        ('3', 8)
    ]

    valid_schedules = []

    for perm in itertools.permutations(movies):
        # perm is a tuple mapping slots to movies
        # slots[i] gets perm[i]
        sched = {slots[i]: perm[i] for i in range(5)}

        # Helper to find movie's slot
        def get_slot(m):
            for s, mov in sched.items():
                if mov == m:
                    return s
            return None

        def get_time(m):
            for s, mov in sched.items():
                if mov == m:
                    return s[1]
            return None

        # 1. Western begins before Horror
        if get_time('W') >= get_time('H'):
            continue

        # 2. Sci-fi is not on screen 3
        if get_slot('S')[0] == '3':
            continue

        # 3. Romance is not on screen 2
        if get_slot('R')[0] == '2':
            continue

        # 4. Horror and Mystery are on different screens
        if get_slot('H')[0] == get_slot('M')[0]:
            continue

        # Additional condition for this question: Romance begins before Western
        if get_time('R') >= get_time('W'):
            continue

        valid_schedules.append(sched)

    # Check options
    options = {
        'A': lambda s: [m for m, sc in s.items() if sc == 'H'][0][0] == '1', # Horror on screen 1
        'B': lambda s: [m for m, sc in s.items() if sc == 'M'][0][1] == 7, # Mystery begins at 7 PM
