        'E': lambda s: [m for m, sc in s.items() if sc == 'S'][0][0] == '2', # Sci-fi on screen 2
    }

    true_options = []
    for opt, check in options.items():
        if all(check(s) for s in valid_schedules):
            true_options.append(opt)

    ans = true_options[0] if len(true_options) == 1 else "UNSUPPORTED"
    print(json.dumps({"final_answer": ans, "evidence": f"valid_count={len(valid_schedules)}, true_options={true_options}"}))

if __name__ == '__main__':
    solve()
